-- Public area labels and IDs follow current canonical geography.
CREATE OR REPLACE VIEW public_providers AS SELECT p.id,p.slug,p.name,p.description,p.categories,ARRAY(SELECT d.name FROM districts d JOIN cities ci ON ci.id=d.city_id WHERE ci.slug=p.city AND d.status='active' AND d.id=ANY(p.district_ids) ORDER BY d.name,d.id) districts,p.city,p.version,
 CASE WHEN p.owner_id IS NULL AND p.provenance='synthetic_seed' THEN p.photos ELSE ARRAY(SELECT '/api/v1/media/'||pm.asset_id||'/view' FROM provider_portfolio pm JOIN media_assets a ON a.id=pm.asset_id WHERE pm.provider_id=p.id AND a.owner_id=p.owner_id AND a.version=pm.asset_version AND a.visibility='public' AND a.status='approved' AND a.scan_at IS NOT NULL AND a.purpose='photo' ORDER BY pm.position) END photos,
 coalesce((SELECT jsonb_agg(jsonb_build_object('url','/api/v1/media/'||pm.asset_id||'/view','alt',pm.alt,'caption',pm.caption) ORDER BY pm.position) FROM provider_portfolio pm JOIN media_assets a ON a.id=pm.asset_id WHERE pm.provider_id=p.id AND a.owner_id=p.owner_id AND a.version=pm.asset_version AND a.visibility='public' AND a.status='approved' AND a.scan_at IS NOT NULL AND a.purpose='photo'),'[]') portfolio,ARRAY(SELECT d.id FROM districts d JOIN cities ci ON ci.id=d.city_id WHERE ci.slug=p.city AND d.status='active' AND d.id=ANY(p.district_ids) ORDER BY d.name,d.id) AS "districtIds"
 FROM providers p WHERE p.status='approved' AND EXISTS(SELECT 1 FROM districts d JOIN cities ci ON ci.id=d.city_id WHERE ci.slug=p.city AND d.status='active' AND d.id=ANY(p.district_ids)) AND EXISTS(SELECT 1 FROM cities ci WHERE ci.slug=p.city AND ci.status='active') AND (p.owner_id IS NULL AND p.provenance='synthetic_seed' OR EXISTS(SELECT 1 FROM profiles pr JOIN memberships m ON m.user_id=pr.id AND m.organization_id=p.organization_id WHERE pr.id=p.owner_id AND pr.state='active' AND m.status='active' AND m.role='vendor'));
